/** The chip a file wears in the tree and the tabs, by its extension: a short label and a colour. Pure. */
export function chipOf(path: string): { label: string; color: string } {
  const ext = (path.split("/").pop() ?? "").split(".").pop()?.toLowerCase() ?? ""; const m: Record<string, [string, string]> = { tsx: ["TSX", "#3b7bd8"], ts: ["TS", "#3178c6"], js: ["JS", "#c9a227"], jsx: ["JSX", "#c9a227"], mjs: ["JS", "#c9a227"], css: ["CSS", "#9b59d0"], scss: ["SCSS", "#c6538c"], html: ["HTML", "#e0653a"], json: ["{}", "#5a9a58"], md: ["MD", "#8f8b81"], rs: ["RS", "#c97c5c"], py: ["PY", "#3b7bd8"], go: ["GO", "#2aa9c4"], yml: ["YML", "#cb6d6d"], yaml: ["YML", "#cb6d6d"], toml: ["TML", "#8f8b81"], sh: ["SH", "#5a9a58"], svg: ["SVG", "#d98f2b"], png: ["IMG", "#8f8b81"] };
  const [label, color] = m[ext] ?? [(ext || "·").slice(0, 3).toUpperCase(), "#8f8b81"]; return { label, color };
}
type TNode = { name: string; path: string; dir: boolean; kids: TNode[] };
/** The nested tree of a list of relative paths: folders first, then files, each alphabetical. Pure. */
export function treeOf(paths: string[]): TNode[] {
  const root: TNode = { name: "", path: "", dir: true, kids: [] };
  for (const p of [...new Set(paths)]) { let cur = root; const parts = p.split("/"); parts.forEach((part, i) => { const path = parts.slice(0, i + 1).join("/"); let n = cur.kids.find((k) => k.name === part && k.dir === (i < parts.length - 1)); if (!n) { n = { name: part, path, dir: i < parts.length - 1, kids: [] }; cur.kids.push(n); } cur = n; }); }
  const sort = (n: TNode) => { n.kids.sort((a, b) => Number(b.dir) - Number(a.dir) || a.name.localeCompare(b.name)); n.kids.forEach(sort); }; sort(root); return root.kids;
}
